<?= view('layout/header', ['title' => 'Products']) ?><h1>Products</h1><p><a class="button" href="<?= site_url('products/new') ?>">Add product</a></p><div class="panel table-wrap"><table><thead><tr><th>Image</th><th>Name</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?php if ($url = \App\Libraries\ImageUpload::url($item['image'], 'products')): ?><img class="thumb" src="<?= esc($url, 'attr') ?>" alt="<?= esc($item['name'], 'attr') ?>"><?php else: ?>—<?php endif ?></td><td><?= esc($item['name']) ?></td><td>₱<?= number_format((float)$item['price'], 2) ?></td><td><?= esc($item['stock_quantity']) ?></td><td><div class="actions"><a href="<?= site_url('products/' . $item['id'] . '/edit') ?>">Edit</a><form method="post" action="<?= site_url('products/' . $item['id'] . '/archive') ?>" onsubmit="return confirm('Archive this product?')"><?= csrf_field() ?><button class="danger">Archive</button></form></div></td></tr><?php endforeach ?><?php if (! $items): ?><tr><td colspan="5">No products yet.</td></tr><?php endif ?></tbody></table></div><?= view('layout/footer') ?>
